k = int(input().strip())
result = ''
for ch in s:
    if 'a' <= ch <= 'z':
        result += chr((ord(ch) - ord('a') + k) % 26 + ord('a'))
    elif 'A' <= ch <= 'Z':
        result += chr((ord(ch) - ord('A') + k) % 26 + ord('A'))
    else:
        result += ch
print(result)

s = input().strip()
if len(s) < 4 or s[0].isdigit():
    print(0)
