n = int(input())
arr = list(map(int, input().split()))
swaps = 0
for i in range(n - 1):
    for j in range(n - 1 - i):
        if arr[j] > arr[j + 1]:
            arr[j], arr[j + 1] = arr[j + 1], arr[j]
            swaps += 1
print(swaps)

num = input().strip()
odd_sum = 0
even_sum = 0
for i, ch in enumerate(reversed(num)):
    d = int(ch)
    if (i + 1) % 2 == 1:
        odd_sum += d
    else:
        even_sum += d
print(abs(odd_sum - even_sum))

n = input().strip()
p = len(n)
if int(n) == sum(int(d) ** p for d in n):
    print('Yes')
else:
    print('No')

n = int(input())
if n < 2:
    print('Not Prime')
else:
    is_prime = True
    d = 2
    while d * d <= n:
        if n % d == 0:
            is_prime = False
            break
        d += 1
    print('Prime' if is_prime else 'Not Prime')
